(()=>{
const q=s=>document.querySelector(s),panel=q('.instrument-panel'),deck=q('.performance-deck'),strip=q('.preset-strip');panel.prepend(q('header'));deck.after(q('.transport'));q('.transport').append(q('.control-pod'));
const picker=document.createElement('button');picker.className='sound-picker';picker.setAttribute('aria-label','Choose instrument');picker.setAttribute('aria-expanded','false');picker.setAttribute('aria-controls','soundDrawer');picker.innerHTML='<span class="picker-chevron">⌄</span>';q('.instrument-name').before(picker);picker.prepend(q('.instrument-name'));strip.id='soundDrawer';strip.setAttribute('aria-label','Instrument selection');
const close=()=>{strip.classList.remove('is-open');picker.setAttribute('aria-expanded','false');};picker.onclick=()=>{const open=strip.classList.toggle('is-open');picker.setAttribute('aria-expanded',String(open));};strip.addEventListener('click',e=>{if(e.target.closest('[data-instrument]'))close();});document.addEventListener('pointerdown',e=>{if(!strip.contains(e.target)&&!picker.contains(e.target))close();});document.addEventListener('keydown',e=>{if(e.key==='Escape')close();});
const canvas=q('#resonator');canvas.setAttribute('aria-label','Grand piano interior with note-reactive lighting');canvas.style.cursor='default';q('#resetCamera').remove();q('.signal-led').title='Audio signal';q('.view-tools').setAttribute('aria-hidden','true');
const image=document.createElement('img');image.className='grand-interior';image.src='assets/grand-interior.png';image.alt='Bronze frame, copper strings and felt hammers inside a grand piano';image.draggable=false;q('.play-art').prepend(image);
const glass=document.createElement('div');glass.className='grand-glass';glass.setAttribute('aria-hidden','true');q('.play-art').append(glass);
q('.brand').setAttribute('aria-label','Quite Room keyboard studio');q('#midiLabel').textContent='MIDI';q('#help').title='Keyboard shortcuts and help';
const c=canvas.getContext('2d'),amplitudes=new Float32Array(36);let last=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)');
window.drawResonator=(now,analyser,notes,base)=>{if(now-last<32)return;last=now;const rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;const dpr=Math.min(devicePixelRatio||1,2),w=rect.width,h=rect.height;if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);for(let n=0;n<36;n++){const pressed=notes.has(base+n);amplitudes[n]=reduced.matches?(pressed?1:0):amplitudes[n]*.8+(pressed?1:0)*.2;const a=amplitudes[n];if(a<.005)continue;const x=(n+.5)/36*w,glow=c.createRadialGradient(x,h*.73,0,x,h*.73,w/19);glow.addColorStop(0,`rgba(255,223,166,${a*.23})`);glow.addColorStop(1,'rgba(255,203,119,0)');c.fillStyle=glow;c.fillRect(x-w/19,0,w/9,h);c.strokeStyle=`rgba(255,225,176,${a*.2})`;c.lineWidth=.65;c.beginPath();c.moveTo(x,h*.69);c.lineTo(w*.08+x*.84,h*.1);c.stroke();if(image.complete&&image.naturalWidth&&w/h>=2.4&&!reduced.matches){const sw=image.naturalWidth/36,sx=n*sw,sy=image.naturalHeight*.68,sh=image.naturalHeight*.23;c.globalAlpha=a*.7;c.drawImage(image,sx,sy,sw,sh,n/36*w,h*.68-a*3,w/36,h*.23);c.globalAlpha=1;}}q('.signal-led').classList.toggle('lit',notes.size>0);};
})();
